let F=[],FD=[],state=null,id=null,rev=0,dirty=false,busy=false,gen=0,timer,tab='catalogue',sessions=[],results=[],filters={},query='',kind='Programme',edition='2026',year='',sourceTime='';const expanded=new Set();
