function changed(){dirty=true;gen++;$('#status').textContent='Wijzigingen · nog niet opgeslagen';clearTimeout(timer);timer=setTimeout(()=>save(),1400)}
async function save(finish=false){if(!state||busy)return;if(!dirty&&id&&!finish)return;busy=true;const g=gen;$('#status').textContent='Opslaan…';try{const d=await api('/api/save',{id,revision:rev,state:structuredClone(state),finish});id=d.id;rev=d.revision;dirty=g!==gen;$('#status').textContent='Opgeslagen in SQL · '+new Date(d.updated).toLocaleTimeString();await listing();if(finish){sessions=(await api('/api/workspaces/'+id)).sessions;render();say('Sessie opgeslagen')}}catch(e){say(e.message+' Exporteer JSON als reservekopie.');$('#status').textContent='Opslaan mislukt'}finally{busy=false;if(dirty&&g!==gen)timer=setTimeout(()=>save(),500)}}
