async function course(path){say('Broninformatie ophalen…');try{const c=await api('/api/course',{path});dialog(c.metadata.Name||c.metadata.Naam||path.split('/').pop(),`<p class="subtle"><a href="${E(c.source)}" target="_blank" rel="noopener">Open catalogusbron</a> · ${E(new Date(c.fetched).toLocaleString())}</p><p>${E(Object.entries(c.metadata).filter(([k])=>k!=='Coordinator').map(([k,v])=>k+': '+v).join(' · '))}</p>${!c.outcomes.trim()?'<p class="warning">Geen leeruitkomsten gevonden: bespreek actualisatie van de bron.</p>':''}<h3>Leeruitkomsten</h3><div class="source">${E(c.outcomes||'Niet gevonden')}</div><h3>Inhoud</h3><div class="source">${E(c.content||'Niet gevonden')}</div><p class="hint">De bron wordt live opgehaald; je mappings blijven ongewijzigd.</p><button id="refresh">Opnieuw ophalen</button>`);$('#refresh').onclick=()=>{$('#dialog').close();course(path)}}catch(e){say('Vak niet opgehaald: '+e.message)}}
function courseKey(m,c){return m.id+'::'+encodeURIComponent(c.code)}
function childMaps(o,m){return m.courses.map(c=>state.mappings[o.id+'|'+courseKey(m,c)]).filter(a=>a?.status&&a.status!=='unreviewed')}
function matrix(v){const ms=state.modules.filter(m=>!year||String(m.year)===year).slice().sort((a,b)=>a.year-b.year),cols=[];ms.forEach(m=>{cols.push({m});if(expanded.has(m.id))m.courses.forEach(c=>cols.push({m,c}))});v.innerHTML=`<h2>Competentiematrix · modules en deelvakken</h2><p class="hint">Elk deelvak heeft een eigen Osiris-code en mapping. Een moduleoverzicht is geen bewijs dat alle deelvakken een competentie behandelen. Studentjaar en competentieniveau zijn verschillende dimensies.</p><div class="filters"><select id="year"><option value="">Alle studentjaren</option>${[...new Set(state.modules.map(m=>m.year))].sort().map(y=>`<option value="${y}" ${String(y)===year?'selected':''}>Jaar ${y}</option>`).join('')}</select><button id="expandAll">Alle deelvakken tonen</button><button id="collapseAll">Alleen modules</button></div><div class="scroll"><table><thead><tr><th>DigComp 3.0 leeruitkomst</th>${cols.map(({m,c})=>c?`<th class="subcourse">${E(c.code)}<br>${E(c.name)}<br><small>${E(m.name)}</small></th>`:`<th>Jaar ${m.year}<br>${E(m.name)}${m.elective?'<br>Keuzeonderwijs':''}<br>${m.courses.length?`<button data-expand="${E(m.id)}">${expanded.has(m.id)?'−':'+'} ${m.courses.length} deelvakken</button>`:''}</th>`).join('')}</tr></thead><tbody>${F.map(o=>`<tr><td class="outcome" style="--domain:${o.color}"><strong>${E(o.domain)}</strong>${E(o.level)}<details><summary>Lees leeruitkomst</summary>${E(o.text)}</details></td>${cols.map(({m,c})=>{const k=o.id+'|'+(c?courseKey(m,c):m.id),a=state.mappings[k]||{},st=a.status||'unreviewed',cs=c?[]:childMaps(o,m),counts={};cs.forEach(x=>counts[x.status]=(counts[x.status]||0)+1);return `<td class="cell ${c?'subcourse':''}">${cs.length?`<strong>${cs.length}/${m.courses.length} deelvakken besproken</strong><p>${Object.entries(counts).map(([k,n])=>n+' × '+E(ST[k])).join('<br>')}</p>`:''}<button data-map="${E(k)}" class="s-${E(st)}">${!c?'Modulebreed: ':''}${E(ST[st])}${a.evidence?'<br>↳ Onderbouwing':''}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;$('#year').onchange=e=>{year=e.target.value;render()};v.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{const k=b.dataset.expand;expanded.has(k)?expanded.delete(k):expanded.add(k);render()});$('#expandAll').onclick=()=>{ms.forEach(m=>expanded.add(m.id));render()};$('#collapseAll').onclick=()=>{expanded.clear();render()};v.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>mapping(b.dataset.map))}
function mapping(key){const [oid,entity]=key.split('|'),[mid,code]=entity.split('::'),m=state.modules.find(m=>m.id===mid),c=code?m.courses.find(c=>c.code===decodeURIComponent(code)):null,o=F.find(o=>o.id===oid),a=state.mappings[key]||{};dialog(c?c.code+' · '+c.name:m.name,`<p style="border-left:7px solid ${o.color};padding-left:12px">${E(o.domain)} · ${E(o.level)}</p><details><summary>Lees DigComp leeruitkomst</summary>${E(o.text)}</details>`+select('Teamkeuze','status',ST,a.status||'unreviewed')+(!c?select('Onderbouwend vak','course',Object.fromEntries([['','Modulebreed'],...m.courses.map(c=>[c.code,c.code+' · '+c.name])]),a.course||''):'')+area('Onderbouwing / leeractiviteit','evidence',a.evidence||'')+area('Toetsing','assessment',a.assessment||'')+area('Rationale / gesprek','rationale',a.rationale||''),d=>{if(c)d.course=c.code;const selected=c||m.courses.find(c=>c.code===d.course);d.source=selected?.path?'https://catalogue.hanze.nl'+selected.path:'';state.mappings[key]=d})}
function targets(v){const ds=[...new Set(F.map(o=>o.domain))];v.innerHTML='<h2>Relevantie & beoogd eindniveau</h2><div class="cards">'+ds.map((d,i)=>{const t=state.targets[d]||{},o=F.find(o=>o.domain===d);return `<article class="card domain" style="--domain:${o.color}"><h3>${E(d)}</h3><p>${E(t.relevance||'Nog niet besproken')}</p><p>Eindniveau: ${E(t.level||'Nog niet bepaald')}</p><p>${E(t.rationale||'')}</p><button data-target="${i}">Bespreken</button></article>`}).join('')+'</div>';v.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{const d=ds[+b.dataset.target],t=state.targets[d]||{};dialog(d,select('Relevantie','relevance',{'Nog niet besproken':'Nog niet besproken',Relevant:'Relevant','Bewust niet relevant':'Bewust niet relevant'},t.relevance||'Nog niet besproken')+select('Eindniveau','level',{'':'Nog niet bepaald',...Object.fromEntries(F.filter(o=>o.domain===d).map(o=>[o.level,(['I — Starten','II — Toepassen','III — Verdiepen','IV — Richting geven'][['I','II','III','IV'].indexOf((o.level.match(/^(IV|III|II|I)/)||[])[1])]||o.level)]))},t.level||'')+area('Onderbouwing','rationale',t.rationale||''),x=>state.targets[d]=x)})}
let SETS=[];
