function useSet(sid,force){const s=SETS.find(x=>x.id===sid);if(!s)return false;const c=state.custom;if(!force&&c?.outcomes?.length&&setDirty(c)&&!confirm('De huidige eigen competenties zijn niet (volledig) als set opgeslagen en worden vervangen. Doorgaan?'))return false;state.custom={name:s.name,setId:s.id,outcomes:structuredClone(s.outcomes)};state.framework='custom';return true}
