const libLev=l=>{const i=LIB_LEVELS.indexOf(l);return i<0?libT(l||'Zonder niveau','No level'):libT(l,libDict[l]||LIB_LEVEL_EN[i]);};
const libStat=s=>({Concept:libT('Concept','Draft'),Beproefd:libT('Beproefd','Tested'),Gevalideerd:libT('Gevalideerd','Validated')})[s]||s;
const libTrOf=i=>libLang()==='en'&&i.source==='curated'?libTr[i.id]:null;
const libF=(i,k)=>{const t=libTrOf(i);return (t&&t[k])||i[k]||'';};
const libTags=i=>{const t=libTrOf(i);return (t&&t.tags)||i.tags||[];};
async function libReload(){libItems=await api('/api/library');if(!libOutcomes.length){try{const r=await api('/api/library/outcomes');libOutcomes=r.outcomes||[];libDict=(r.dict&&!Array.isArray(r.dict))?r.dict:{};}catch(e){libOutcomes=[];}try{libTr=await api('/api/library/translations')||{};}catch(e){libTr={};}}}
setInterval(()=>{if(libShown&&typeof tab!=='undefined'&&tab==='library'&&libLang()!==libShown)render();},600);
function libraryView(v){
 if(libItems===null){v.innerHTML='<h2>'+libT('Bibliotheek','Library')+'</h2><p>'+libT('Laden...','Loading...')+'</p>';libReload().catch(e=>{libItems=[];say(libT('Bibliotheek niet geladen: ','Library could not be loaded: ')+e.message);}).finally(()=>{if(tab==='library')render();});return;}
 libShown=libLang();
 const intro=libT('Honderd uitgewerkte leeractiviteiten voor het hoger onderwijs: vijf per niveau van elke leeruitkomst, twintig per DigComp 3.0-domein. De startvoorbeelden zijn eigen ontwerpen (status Concept). Pas casus, bronnen en beoordeling aan je opleiding aan en markeer ze als Beproefd of Gevalideerd zodra je ze hebt gebruikt of laten toetsen.','One hundred worked-out learning activities for higher education: five per level of each learning outcome, twenty per DigComp 3.0 domain. The starter examples are original designs (status Draft). Adapt the case, sources and assessment to your programme and mark them as Tested or Validated once you have used them or had them reviewed.');
 v.innerHTML=`<h2>${libT('Didactische bibliotheek: digitale &amp; AI-geletterdheid','Teaching library: digital &amp; AI literacy')}</h2><p class="hint">${libS(intro)}</p><div class="filters"><input id="libQ" type="search" placeholder="${libS(libT('Zoeken op titel, werkvorm of tag','Search by title, activity or tag'))}" value="${libS(libFilter.q)}"><label class="subtle">${libT('Domein','Domain')} <select id="libDomain"><option value="">${libT('Alle domeinen','All domains')}</option>${LIB_DOMAINS.map(d=>`<option value="${libS(d)}"${libFilter.domain===d?' selected':''}>${libS(libDom(d))}</option>`).join('')}</select></label><label class="subtle">${libT('Niveau','Level')} <select id="libLevel"><option value="">${libT('Alle niveaus','All levels')}</option>${LIB_LEVELS.map(l=>`<option value="${libS(l)}"${libFilter.level===l?' selected':''}>${libS(libLev(l))}</option>`).join('')}</select></label><label class="subtle">${libT('Herkomst','Source')} <select id="libSrc"><option value="">${libT('Alle','All')}</option><option value="curated"${libFilter.source==='curated'?' selected':''}>${libT('Startvoorbeelden','Starter examples')}</option><option value="handmatig"${libFilter.source==='handmatig'?' selected':''}>${libT('Handmatig toegevoegd','Added manually')}</option></select></label><button id="libAdd" class="primary">${libT('Voorbeeld toevoegen','Add example')}</button><button id="libExport">${libT('Exporteer (JSON)','Export (JSON)')}</button></div><p class="subtle" id="libCount"></p><div id="libGroups"></div>`;
 const badge=t=>t?`<span style="display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid currentColor;font-size:.8em;margin:0 6px 4px 0">${libS(t)}</span>`:'';
 const row=(l,t)=>t?`<p><strong>${l}:</strong> ${libS(t)}</p>`:'';
 const card=(i,n)=>`<article class="card"><h4>${n}. ${libS(libF(i,'title'))}</h4><p>${badge(libLev(i.level))}${badge(i.outcome?libT('Leeruitkomst ','Learning outcome ')+i.outcome:'')}${badge(libStat(i.status))}${badge(libF(i,'duration'))}${badge(i.source==='handmatig'?libT('Handmatig toegevoegd','Added manually'):libT('Startvoorbeeld','Starter example'))}</p>${row(libT('Leerdoel','Learning goal'),libF(i,'summary'))}<details><summary>${libT('Werkvorm, rol van AI en beoordeling','Activity, role of AI and assessment')}</summary>${row(libT('Werkvorm','Activity'),libF(i,'activity'))}${row(libT('Rol van AI','Role of AI'),libF(i,'ai_role'))}${row(libT('Opbrengst','Output'),libF(i,'output'))}${row(libT('Beoordeling','Assessment'),libF(i,'assessment'))}${i.institution&&i.institution!=='Redactie DigComp Compass'?`<p class="subtle">${libT('Ingebracht door','Contributed by')}: ${libS(i.institution)}</p>`:''}${/^https?:/i.test(i.url||'')?`<p><a href="${libS(i.url)}" target="_blank" rel="noopener noreferrer">${libT('Open aanvullende bron','Open additional source')}</a></p>`:''}</details><p class="subtle">${libTags(i).map(libS).join(' | ')}</p><p><button data-edit="${libS(i.id)}">${libT('Bewerken','Edit')}</button> <button data-del="${libS(i.id)}">${libT('Verwijderen','Delete')}</button></p></article>`;
 const match=i=>{const q=libFilter.q.trim().toLowerCase();return (!q||[libF(i,'title'),i.institution,libF(i,'summary'),libF(i,'activity'),libF(i,'ai_role'),libF(i,'output'),libF(i,'assessment'),libTags(i).join(' ')].join(' ').toLowerCase().includes(q))&&(!libFilter.domain||i.domain===libFilter.domain)&&(!libFilter.level||i.level===libFilter.level)&&(!libFilter.source||i.source===libFilter.source)};
 const draw=()=>{
  const list=libItems.filter(match);$('#libCount').textContent=list.length+libT(' van ',' of ')+libItems.length+libT(' voorbeelden',' examples');
  const groups=[...LIB_DOMAINS,'Zonder domein'];
  $('#libGroups').innerHTML=groups.map(d=>{
   const inDomain=list.filter(i=>d==='Zonder domein'?!LIB_DOMAINS.includes(i.domain):i.domain===d);if(!inDomain.length)return '';
   const levels=[...LIB_LEVELS,'Zonder niveau'].map(l=>{
    const xs=inDomain.filter(i=>l==='Zonder niveau'?!LIB_LEVELS.includes(i.level):i.level===l);if(!xs.length)return '';
    const oc=libOutcomes.find(o=>o.domain===d&&o.level===l);
    const ocText=oc?(libLang()==='en'?(libDict[oc.text]||oc.text_en||oc.text):oc.text):'';
    return `<h3>${libT('Niveau ','Level ')}${libS(libLev(l))} <small class="subtle">(${xs.length})</small></h3>${oc?`<details><summary>${libT('Leeruitkomst ','Learning outcome ')}${libS(oc.id)}</summary><p>${libS(ocText)}</p></details>`:''}<div class="cards">${xs.map((i,n)=>card(i,n+1)).join('')}</div>`}).join('');
   return `<section style="border-left:8px solid ${LIB_COLORS[d]};padding-left:14px;margin:28px 0"><h2>${libS(libDom(d))} <small class="subtle">(${inDomain.length})</small></h2>${levels}</section>`}).join('')||'<p>'+libT('Geen voorbeelden gevonden voor deze filters.','No examples found for these filters.')+'</p>';
  document.querySelectorAll('#libGroups [data-edit]').forEach(b=>b.onclick=()=>libForm(libItems.find(i=>i.id===b.dataset.edit)));
  document.querySelectorAll('#libGroups [data-del]').forEach(b=>b.onclick=async()=>{const it=libItems.find(i=>i.id===b.dataset.del);if(!confirm(libT('Dit voorbeeld verwijderen? ','Delete this example? ')+libF(it,'title')))return;try{await api('/api/library/delete',{id:it.id});await libReload();render();say(libT('Voorbeeld verwijderd','Example deleted'));}catch(e){say(e.message);}});
 };
 draw();
 $('#libQ').oninput=e=>{libFilter.q=e.target.value;draw();};$('#libDomain').onchange=e=>{libFilter.domain=e.target.value;draw();};$('#libLevel').onchange=e=>{libFilter.level=e.target.value;draw();};$('#libSrc').onchange=e=>{libFilter.source=e.target.value;draw();};
 $('#libAdd').onclick=()=>libForm(null);
 $('#libExport').onclick=()=>download('didactische-bibliotheek-digitale-en-ai-geletterdheid.json',JSON.stringify(libItems,null,2));
}
function libForm(item){
 const it=item||{};
 const f=(l,n,v)=>`<label>${libS(l)}<input name="${n}" value="${libS(v)}"></label>`;
 const a=(l,n,v)=>`<label>${libS(l)}<textarea name="${n}" rows="3">${libS(v)}</textarea></label>`;
 const s=(l,n,list,show,cur)=>`<label>${libS(l)}<select name="${n}">${list.map(x=>`<option value="${libS(x)}"${x===cur?' selected':''}>${libS(show(x))}</option>`).join('')}</select></label>`;
 dialog(item?libT('Didactisch voorbeeld bewerken','Edit teaching example'):libT('Didactisch voorbeeld toevoegen','Add teaching example'),`<form id="libForm">${f(libT('Titel (verplicht)','Title (required)'),'title',it.title)}${s(libT('DigComp-domein','DigComp domain'),'domain',LIB_DOMAINS,libDom,it.domain||LIB_DOMAINS[0])}${s(libT('Niveau van de leeruitkomst','Level of the learning outcome'),'level',LIB_LEVELS,libLev,it.level||LIB_LEVELS[0])}${a(libT('Leerdoel','Learning goal'),'summary',it.summary)}${a(libT('Werkvorm: wat doen studenten?','Activity: what do students do?'),'activity',it.activity)}${a(libT('Rol van AI: met, zonder of beperkt','Role of AI: with, without or limited'),'ai_role',it.ai_role)}${a(libT('Opbrengst of bewijs','Output or evidence'),'output',it.output)}${a(libT('Beoordeling','Assessment'),'assessment',it.assessment)}${f(libT('Duur','Duration'),'duration',it.duration)}${f(libT('Ingebracht door / instelling','Contributed by / institution'),'institution',it.institution)}${f(libT('Optionele link (http:// of https://)','Optional link (http:// or https://)'),'url',it.url)}${f(libT("Tags (gescheiden door komma's)",'Tags (comma-separated)'),'tags',(it.tags||[]).join(', '))}${s('Status','status',['Concept','Beproefd','Gevalideerd'],libStat,it.status||'Concept')}<button class="primary">${libT('Opslaan','Save')}</button></form>`);
 $('#libForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),btn=e.target.querySelector('button');btn.disabled=true;try{await api(item?'/api/library/update':'/api/library',item?{id:item.id,item:d}:{item:d});await libReload();const dlg=document.querySelector('dialog[open]');if(dlg)dlg.close();render();say(item?libT('Voorbeeld bijgewerkt','Example updated'):libT('Voorbeeld toegevoegd','Example added'));}catch(er){say(er.message);btn.disabled=false;}};
}
async function manageWorkspaces(){
 const en=catalogueLanguage()==='en',pick=(nl,eng)=>en?eng:nl;
 if(busy){say(pick('Wacht tot het opslaan klaar is.','Wait until saving finishes.'));return;}
 try{
 const workspaces=await api('/api/workspaces?all=1');
 dialog(pick('Werkruimtes beheren','Manage workspaces'),'<div data-no-translate><p>'+pick('Selecteer testwerkruimtes. Verwijderen verwijdert ook de bijbehorende sessies.','Select test workspaces. Deletion also removes their saved sessions.')+'</p><label><input type="checkbox" id="workspaceSelectAll"> '+pick('Alles selecteren','Select all')+'</label><div class="scroll">'+workspaces.map(w=>'<label class="field"><span><input type="checkbox" data-workspace-id="'+E(w.id)+'"> '+E(w.name)+(w.archived?' · '+pick('gearchiveerd','archived'):'')+(w.id===id?' · '+pick('actief','active'):'')+'</span><small>'+E(new Date(w.updated).toLocaleString(en?'en-GB':'nl-NL'))+'</small></label>').join('')+(workspaces.length?'':'<p>'+pick('Geen opgeslagen werkruimtes.','No saved workspaces.')+'</p>')+'</div><button id="workspaceBackup">'+pick('Exporteer geselecteerde werkruimtes','Export selected workspaces')+'</button> <button id="workspaceArchive">'+pick('Archiveer geselecteerde','Archive selected')+'</button> <button id="workspaceRestore">'+pick('Haal uit archief','Unarchive')+'</button> <button id="workspaceDelete">'+pick('Verwijder geselecteerde werkruimtes','Delete selected workspaces')+'</button></div>');
 const selected=()=>[...document.querySelectorAll('[data-workspace-id]:checked')].map(x=>workspaces.find(w=>w.id===x.dataset.workspaceId));
 $('#workspaceSelectAll').onchange=e=>document.querySelectorAll('[data-workspace-id]').forEach(x=>x.checked=e.target.checked);
 $('#workspaceBackup').onclick=async()=>{const chosen=selected();if(!chosen.length){say(pick('Selecteer eerst werkruimtes.','Select workspaces first.'));return;}try{const d=await api('/api/workspaces/export',{ids:chosen.map(w=>w.id)});download('compass-workspaces-backup.json',JSON.stringify(d,null,2));}catch(e){say(e.message);}};
 const archiveSelected=async flag=>{const chosen=selected();if(!chosen.length){say(pick('Selecteer eerst werkruimtes.','Select workspaces first.'));return;}try{await api('/api/workspaces/archive',{ids:chosen.map(w=>w.id),archived:flag});$('#dialog').close();await listing();say(flag?pick('Werkruimtes gearchiveerd.','Workspaces archived.'):pick('Werkruimtes teruggehaald uit het archief.','Workspaces restored from the archive.'));}catch(e){say(e.message);}};
 $('#workspaceArchive').onclick=()=>archiveSelected(true);$('#workspaceRestore').onclick=()=>archiveSelected(false);
 $('#workspaceDelete').onclick=async()=>{
 const chosen=selected();if(!chosen.length){say(pick('Selecteer eerst werkruimtes.','Select workspaces first.'));return;}
 if(busy){say(pick('Wacht tot het opslaan klaar is.','Wait until saving finishes.'));return;}
 if(chosen.some(w=>w.id===id)&&dirty){say(pick('Sla de actieve werkruimte eerst op of exporteer wijzigingen; open daarna dit venster opnieuw.','Save the active workspace or export changes first, then reopen this window.'));return;}
 if(!confirm(pick('Deze werkruimtes en hun sessies verwijderen?','Delete these workspaces and their sessions?')+'\n\n'+chosen.map(w=>w.name).join('\n')))return;
 const button=$('#workspaceDelete');button.disabled=true;
 try{const d=await api('/api/workspaces/delete',{confirmed:true,workspaces:chosen.map(w=>({id:w.id,revision:w.revision}))});
 if(chosen.some(w=>w.id===id)){clearTimeout(timer);state=null;id=null;rev=0;dirty=false;sessions=[];expanded.clear();tab='catalogue';$('#status').textContent='';}
 $('#dialog').close();await listing();render();say(pick('Werkruimtes verwijderd: ','Workspaces deleted: ')+d.deleted);
 }catch(e){say(e.message);button.disabled=false;}
 };
 }catch(e){say(e.message);}
}
